// File and folder icons from the Material Icon Theme (MIT), matched the way
// VS Code matches them. The lookup table is generated by scripts/material-icons.mjs.
import map from "./material-icons.json";
import type { Entry } from "./api";

const icons = map as {
  file: string;
  folder: string;
  fileNames: Record<string, string>;
  fileExtensions: Record<string, string>;
  folderNames: Record<string, string>;
};

const url = (file: string) => `/material-icons/${file}`;

export function materialIcon(entry: Entry): string {
  const name = entry.name.toLowerCase();
  if (entry.isDir) return url(icons.folderNames[name] ?? icons.folder);

  // Exact names first ("package.json", "Dockerfile"), then the longest
  // extension: "app.test.ts" tries "test.ts" before "ts".
  const exact = icons.fileNames[name];
  if (exact) return url(exact);
  for (let i = name.indexOf("."); i >= 0; i = name.indexOf(".", i + 1)) {
    const hit = icons.fileExtensions[name.slice(i + 1)];
    if (hit) return url(hit);
  }
  return url(icons.file);
}
